def calculate_utilizations(task_set):
    gamma_LO = [t for t in task_set if t.L_i == 'LO']
    gamma_HI = [t for t in task_set if t.L_i == 'HI']

    u_LO_i_map = {t: t.C_LO_i / t.T_i for t in task_set}
    u_HI_i_map = {t: t.C_HI_i / t.T_i for t in task_set}

    U_LO_LO = sum(u_LO_i_map[t] for t in gamma_LO)
    U_HI_LO = sum(u_HI_i_map[t] for t in gamma_LO)
    U_LO_HI = sum(u_LO_i_map[t] for t in gamma_HI)
    U_HI_HI = sum(u_HI_i_map[t] for t in gamma_HI)

    U_LO = U_LO_LO + U_LO_HI
    U_HI = U_HI_LO + U_HI_HI

    return {
        'U_LO_LO': U_LO_LO, 'U_HI_LO': U_HI_LO,
        'U_LO_HI': U_LO_HI, 'U_HI_HI': U_HI_HI,
        'U_LO': U_LO, 'U_HI': U_HI
    }

def is_carry_over_job_imc(job_J_i, switch_time_t1):
    if job_J_i.L_i == 'LO':
        if job_J_i.a_i < switch_time_t1 and job_J_i.d_i > switch_time_t1:
            return True
    return False

def is_carry_over_job_emc(job_J_i, switch_time_t1):
    # Assuming job_J_i has an 'original_d_i' attribute for EMC
    if job_J_i.L_i == 'LO':
        if job_J_i.a_i < switch_time_t1 and job_J_i.original_d_i > switch_time_t1:
            return True
    return False

def check_proposition_1(job_set_J, t2_deadline_miss_time):
