    return True # Proposition holds

def check_proposition_2(t1, a1, t2, x):
    # This is a condition that must hold for the mode switch scenario
    return t1 < (a1 + x * (t2 - a1))

def check_proposition_3(job_J_i, u_LO_i, u_HI_i, a1, t2, x, t1):
    # This is a property derived from the minimality assumption of J
    # It's not a direct check, but a condition that must hold if a deadline miss occurs
    if is_carry_over_job_imc(job_J_i, t1) and u_LO_i > u_HI_i:
        # If J_i completed its C_LO_i execution before t1
        # (This part is an assumption for the proposition, not something to check directly)
        # Then its deadline d_i must satisfy:
        return job_J_i.d_i <= (a1 + x * (t2 - a1))
    return True # Condition not applicable or trivially true

def is_schedulable_imc_edf_vd(utilizations):
    U_HI_HI = utilizations['U_HI_HI']
    U_LO_LO = utilizations['U_LO_LO']
    U_HI_LO = utilizations['U_HI_LO']
    U_LO_HI = utilizations['U_LO_HI']

    # Condition 1: Simple EDF schedulability
    if U_HI_HI + U_LO_LO <= 1.0:
        return True, 'EDF'

    # Condition 2: EDF-VD schedulability
    # Check necessary conditions for EDF-VD to be applicable
    if not (U_HI_HI + U_HI_LO < 1.0 and U_LO_LO < 1.0 and U_LO_LO > U_HI_LO):
        return False, 'Conditions for x range not met'

    # Calculate bounds for x from Theorem 1 and Theorem 2
    x_lower_bound = U_LO_HI / (1.0 - U_LO_LO)
    x_upper_bound = (1.0 - (U_HI_HI + U_HI_LO)) / (U_LO_LO - U_HI_LO)

    # Ensure x is within (0, 1) and the bounds are valid
    if x_lower_bound <= x_upper_bound and x_lower_bound < 1.0 and x_upper_bound > 0.0:
        return True, 'EDF-VD', (max(0.0, x_lower_bound), min(1.0, x_upper_bound))
    else:
        return False, 'No valid x range for EDF-VD'

def check_proposition_6(job_J_i, a1, t2, x, t1):
    # This is a property derived from the minimality assumption of J for EMC
    if is_carry_over_job_emc(job_J_i, t1):
        # If J_i completed its C_LO_i execution before t1 (assumption for the proposition)
        return job_J_i.original_d_i <= (a1 + x * (t2 - a1))
    return True # Condition not applicable or trivially true

def is_schedulable_emc_edf_vd(emc_utilizations):
    # This function would call the same logic as is_schedulable_imc_edf_vd
    # but with 'emc_utilizations' which have U_HI_LO calculated using T_max_i
    return is_schedulable_imc_edf_vd(emc_utilizations)

